<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Estudiante,Grado,Seccion,User};use Illuminate\Http\{RedirectResponse,Request};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\Rules\Password;use Illuminate\View\View;
class EstudianteController extends Controller{public function index():View{return view('admin.estudiantes.index',['estudiantes'=>Estudiante::with(['user','grado','seccion'])->paginate(15)]);}public function create():View{return view('admin.estudiantes.create',['grados'=>Grado::orderBy('nombre')->get(),'secciones'=>Seccion::orderBy('nombre')->get()]);}public function store(Request $request):RedirectResponse{$d=$request->validate(['name'=>['required','string','max:255'],'email'=>['required','email','unique:users,email'],'password'=>['required',Password::min(8),'confirmed'],'grado_id'=>['required','exists:grados,id'],'seccion_id'=>['required','exists:secciones,id'],'matricula'=>['required','string','unique:estudiantes,matricula']]);$e=DB::transaction(function()use($d){$u=User::create(['name'=>$d['name'],'email'=>$d['email'],'password'=>$d['password'],'role'=>'estudiante','estado'=>true]);return Estudiante::create(['user_id'=>$u->id,'grado_id'=>$d['grado_id'],'seccion_id'=>$d['seccion_id'],'matricula'=>$d['matricula'],'qr_token'=>Str::random(64)]);});return to_route('admin.estudiantes.show',$e)->with('success','Estudiante creado correctamente.');}public function show(Estudiante $estudiante):View{return view('admin.estudiantes.show',['estudiante'=>$estudiante->load(['user','grado','seccion'])]);}}
